        return false;
    }
    if (n == 2) {
        return true;
    }
    if ((n & 1) == 0) { // Even numbers greater than 2 are not prime
        return false;
    }
    int limit = (int)Math.sqrt(n) + 1;
    for (int i = 3; i <= limit; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

